{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C70"],
      "claim": "Isoniazid, a small orally absorbed drug, has an absolute oral bioavailability of 93% in fasting adult TB patients, supporting high oral availability for small polar molecules with minimal first-pass loss.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Safinamide absolute bioavailability was 95.0% in fasted healthy subjects after a 50 mg IR tablet versus IV, demonstrating that a small molecule with good permeability and low first-pass metabolism can be almost completely orally available.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Fenspiride absolute bioavailability was 90% from an 80 mg slow-release tablet in healthy volunteers, another small molecule with near-complete oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "Atazanavir has an absolute oral bioavailability of 68% (57–80%) in humans, well above the 20% threshold, although it is larger and more lipophilic than the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is benznidazole, a small nitroimidazole drug; analogous small molecules with good permeability and low first-pass metabolism show high oral bioavailability, and no transferable evidence supports F < 20%, so the prediction is high.",
  "evidence_gaps": [
    "No direct benznidazole oral bioavailability measurement is present in the supplied records.",
    "Extrapolation relies on small-molecule analogs rather than a query-specific pharmacokinetic study."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

